function parseAiAnalysis(raw){if(!raw)return null;const clean=s=>s.replace(/\*\*/g,'').trim();const get=key=>{const m=raw.match(new RegExp(key+':\\s*(.+)'));return m?clean(m[1]):'';};const score=parseInt(get('ציון'))||null;const bullets=(get('סיבות')||'').split('|').map(s=>clean(s)).filter(Boolean);const caution=get('לשים לב')||'';const label=get('המלצה')||'';return{score,bullets,caution,label};}// Parse batch AI response for AIRecs (5 pairs in one call)
